#include<bits/stdc++.h>
using namespace std;
const int MOD=1000000007;
inline int addmod(int a,int b){ if((a+=b)>=MOD) a-=MOD; return a; }
inline int mulmod(int a,int b){ long long t=1LL*a*b; if(t>=MOD) t%=MOD; return (int)t; }

struct Matr {
    int m[35][35];
    void clear(){ memset(m,0,sizeof(m)); }
    void identity(){ clear(); for(int i=0;i<35;i++) m[i][i]=1; }
    const int* operator[](int i) const{ return m[i]; }
    int* operator[](int i){ return m[i]; }
};

Matr addMat(const Matr& a, const Matr& b){
    Matr c; c.clear();
    for(int i=0;i<35;i++) for(int j=0;j<35;j++) c[i][j]=addmod(a[i][j],b[i][j]);
    return c;
}
Matr mulScalar(const Matr& a, int x){
    Matr c=a;
    for(int i=0;i<35;i++) for(int j=0;j<35;j++) c[i][j]=mulmod(c[i][j],x);
    return c;
}
Matr mulMat(const Matr& a, const Matr& b){
    Matr c; c.clear();
    for(int i=0;i<35;i++){
        for(int k=0;k<35;k++){
            int aik=a[i][k];
            if(aik){
                for(int j=0;j<35;j++) c[i][j]=addmod(c[i][j],mulmod(aik,b[k][j]));
            }
        }
    }
    return c;
}

typedef long long ll;
ll n;
int K;
vector<int> digit;
Matr A[65][35], S[65][35], P[65][35], ans;

int main(){
    scanf("%lld%d",&n,&K);
    for(int i=0;i<K;i++){
        A[0][i].identity();
        for(int j=0;j<=K;j++) A[0][i][i][j]=1;
    }
    ll len=K;
    for(int i=1; len<=n; i++, len*=K){
        S[i-1][K-1]=A[i-1][K-1];
        for(int j=K-2;j>=0;j--) S[i-1][j]=mulMat(A[i-1][j],S[i-1][j+1]);
        P[i-1][0]=A[i-1][0];
        for(int j=1;j<K;j++) P[i-1][j]=mulMat(P[i-1][j-1],A[i-1][j]);
        A[i][0]=S[i-1][0];
        for(int j=1;j<K;j++) A[i][j]=mulMat(S[i-1][j],P[i-1][j-1]);
    }
    while(n){
        digit.push_back(n%K);
        n/=K;
    }
    int s=0;
    ans.identity();
    for(int i=digit.size()-1;i>=0;i--){
        for(int j=0;j<digit[i];j++)
            ans=mulMat(ans,A[i][(j+s)%K]);
        s=(s+digit[i])%K;
    }
    int res=1;
    for(int i=0;i<K;i++) res=addmod(res,ans[i][K]);
    printf("%d\n",res);
    return 0;
}
